use wado_lsp::test_support::MapHost;
use wado_lsp::{Engine, InlayHint, Position, Range};

async fn hints(source: &str) -> Vec<InlayHint> {
    let path = "/test.wado";
    let uri = format!("file://{path}");
    let host = MapHost::single(path, source);
    let mut engine = Engine::new();
    engine.open_document(&uri, source.to_string());
    let range = Range {
        start: Position { line: 0, character: 0 },
        end: Position { line: u32::MAX, character: u32::MAX },
    };
    engine.inlay_hints(&uri, range, &host).await
}

#[test]
fn probe() {
    futures::executor::block_on(async {
        let srcs = [
            concat!(
                "trait Maker<T> {\n",
                "    fn make(&self) -> T;\n",
                "    fn twice(&self) -> T { let v = self.make(); return v; }\n",
                "}\n",
                "struct A {}\n",
                "struct B {}\n",
                "impl Maker<i32> for A { fn make(&self) -> i32 { return 1; } }\n",
                "impl Maker<String> for B { fn make(&self) -> String { return \"a\"; } }\n",
                "fn run() -> i32 { let a = A {}; let b = B {}; let s = b.twice(); return a.twice(); }\n",
            ),
            concat!(
                "fn id<T>(x: T) -> T { let y = x; return y; }\n",
                "fn run() -> i32 { let s = id(\"a\"); return id(1); }\n",
            ),
            concat!(
                "struct P { x: i32 }\n",
                "impl P { fn sum(&self, k: i32) -> i32 { return self.x + k; } }\n",
                "fn run() -> i32 { let p = P { x: 1 }; return P::sum(&p, 2); }\n",
            ),
            concat!(
                "fn run() -> i32 { let items: Array<i32> = [1, 2]; let mut t: i32 = 0; for let [a, b] of [[1,2]] { t = t + a; } return t; }\n",
            ),
        ];
        for s in srcs {
            let h = hints(s).await;
            eprintln!("=== {s}\n{h:#?}");
        }
    });
}

