#[test]
fn probe_misc() {
    futures::executor::block_on(async {
        show("tuple", &hints("fn run() -> i32 {\n    let (p, q) = (1, 2);\n    return p + q;\n}\n").await);
        show("closure", &hints("fn run() -> i32 {\n    let f = |x| x * 2;\n    return f(1);\n}\n").await);
        show("iflet", &hints("fn run() -> i32 {\n    let o: Option<i32> = Some(3);\n    if let Some(v) = o { return v; }\n    return 0;\n}\n").await);
        show("letmut", &hints("fn run() -> i32 {\n    let mut zz = 1;\n    zz = 2;\n    return zz;\n}\n").await);
        show("ref", &hints("fn run() -> i32 {\n    let a: Array<i32> = [1];\n    let r = &a;\n    return r[0];\n}\n").await);
        show("stdlib", &hints("fn run() -> i32 {\n    let mut a: Array<i32> = [];\n    a.push(1);\n    return a.len();\n}\n").await);
        show("or", &hints("variant E { A(i32), B(i32) }\nfn run(e: E) -> i32 {\n    let x = match e { A(v) | B(v) => v };\n    return x;\n}\n").await);
    });
}

