fn dump(src: &str) {
    let h = futures::executor::block_on(hints(src));
    eprintln!("=== SRC ===\n{src}");
    for x in &h {
        eprintln!("  {}:{} {:?} {}", x.position.line, x.position.character, x.kind, x.label);
    }
}

#[test]
fn probe() {
    dump(concat!(
        "trait Desc {\n",
        "    fn id(&self) -> i32;\n",
        "    fn describe(&self) -> i32 { let me = self; return me.id(); }\n",
        "}\n",
        "struct A { v: i32 }\n",
        "struct B { v: i64 }\n",
        "impl Desc for A { fn id(&self) -> i32 { return 1; } }\n",
        "impl Desc for B { fn id(&self) -> i32 { return 2; } }\n",
        "fn run() -> i32 { let a = A { v: 1 }; return a.describe(); }\n",
    ));
    dump(concat!(
        "fn id<T>(x: T) -> T { let y = x; return y; }\n",
        "fn run() -> i32 { let s = id(\"a\"); return id(3); }\n",
    ));
    dump(concat!(
        "fn add(a: i32, b: i32 = 5) -> i32 { let f = |q| q + a; return f(b); }\n",
        "fn run() -> i32 { let [p, q] = [1, 2]; let t = add(1); return t + p + q; }\n",
    ));
    dump(concat!(
        "fn run() -> i32 {\n",
        "  let mut arr: Array<i32> = [];\n",
        "  arr.push(3);\n",
        "  let v = arr[0];\n",
        "  let g = |x| x;\n",
        "  let o: Option<i32> = Option::<i32>::Some(1);\n",
        "  return v;\n",
        "}\n",
    ));
    dump(concat!(
        "struct P { x: i32 }\n",
        "impl P { fn dist(&self, other: &P) -> i32 { return self.x - other.x; } }\n",
        "fn run() -> i32 { let a = P { x: 1 }; let b = P { x: 2 }; return P::dist(&a, &b); }\n",
    ));
    dump(concat!(
        "fn helper(x: i32) -> i32 { return x; }\n",
        "fn run() -> i32 { let n = 3 |> helper(); return n; }\n",
    ));
}

